import{_ as a,c as n,o as s,ag as r}from"./chunks/framework.CQuhCYrb.js";const h=JSON.parse('{"title":"Matrix Federation with Cloudflare Workers","description":"","frontmatter":{"title":"Matrix Federation with Cloudflare Workers"},"headers":[],"relativePath":"matrix/matrix-federation-with-cloudflare-workers.md","filePath":"matrix/matrix-federation-with-cloudflare-workers.md","lastUpdated":null}'),t={name:"matrix/matrix-federation-with-cloudflare-workers.md"};function o(l,e,p,i,u,c){return s(),n("div",null,[...e[0]||(e[0]=[r(`<h1 id="matrix-federation-with-cloudflare-workers" tabindex="-1">Matrix Federation with Cloudflare Workers <a class="header-anchor" href="#matrix-federation-with-cloudflare-workers" aria-label="Permalink to &quot;Matrix Federation with Cloudflare Workers&quot;">​</a></h1><h2 id="setting-up-matrix-on-cloudflare-workers" tabindex="-1">Setting Up Matrix on Cloudflare Workers <a class="header-anchor" href="#setting-up-matrix-on-cloudflare-workers" aria-label="Permalink to &quot;Setting Up Matrix on Cloudflare Workers&quot;">​</a></h2><p>Cloudflare Workers are a serverless execution environment that allows you to create entirely new applications or augment existing ones without configuring or maintaining infrastructure.</p><p>Source for this guide: <a href="https://appelman.se/matrix-on-cloudflare/" target="_blank" rel="noreferrer">Matrix on Cloudflare</a></p><h3 id="step-by-step-guide" tabindex="-1">Step-by-Step Guide <a class="header-anchor" href="#step-by-step-guide" aria-label="Permalink to &quot;Step-by-Step Guide&quot;">​</a></h3><p>Follow these steps to configure Matrix using Cloudflare Workers:</p><ol><li><p><strong>Log in to your Cloudflare account.</strong> Navigate to the account and domain where you want to create the worker.</p></li><li><p><strong>Navigate to the Workers tab.</strong> This is located on the top menu. Clicking it will bring you to the Workers’ dashboard.</p></li><li><p><strong>Click on the “Create a Worker” button.</strong> This will open a new page with a script template for your worker.</p></li><li><p><strong>Replace the default script with your script.</strong> In the editor, delete the existing script and paste the following script. Replace:</p></li></ol><ul><li><p><code>&quot;https://matrix.example.com&quot;</code> with your actual homeserver URL.</p></li><li><p><code>&quot;https://vector.im&quot;</code> with your identity server URL.</p></li><li><p><code>&quot;matrix-fed.example.com:8443&quot;</code> with your federation server.</p></li></ul><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>const HOMESERVER_URL = &quot;https://matrix.example.com&quot;;</span></span>
<span class="line"><span>const IDENTITY_SERVER_URL = &quot;https://vector.im&quot;;</span></span>
<span class="line"><span>const FEDERATION_SERVER = &quot;matrix-fed.example.com:8443&quot;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>export default {</span></span>
<span class="line"><span>  async fetch(request, env) {</span></span>
<span class="line"><span>    const path = new URL(request.url).pathname;</span></span>
<span class="line"><span>    switch (path) {</span></span>
<span class="line"><span>      case &quot;/.well-known/matrix/client&quot;:</span></span>
<span class="line"><span>        return new Response(</span></span>
<span class="line"><span>          JSON.stringify({</span></span>
<span class="line"><span>            &quot;m.homeserver&quot;: { &quot;base_url&quot;: HOMESERVER_URL },</span></span>
<span class="line"><span>            &quot;m.identity_server&quot;: { &quot;base_url&quot;: IDENTITY_SERVER_URL }</span></span>
<span class="line"><span>          }),</span></span>
<span class="line"><span>          { headers: { &quot;Content-Type&quot;: &quot;application/json&quot; } }</span></span>
<span class="line"><span>        );</span></span>
<span class="line"><span>      case &quot;/.well-known/matrix/server&quot;:</span></span>
<span class="line"><span>        return new Response(</span></span>
<span class="line"><span>          JSON.stringify({ &quot;m.server&quot;: FEDERATION_SERVER }),</span></span>
<span class="line"><span>          { headers: { &quot;Content-Type&quot;: &quot;application/json&quot; } }</span></span>
<span class="line"><span>        );</span></span>
<span class="line"><span>      default:</span></span>
<span class="line"><span>        return new Response(&quot;Invalid request&quot;, { status: 404 });</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  },</span></span>
<span class="line"><span>};</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br></div></div><ol><li><p><strong>Give your worker a name.</strong> The name identifies your worker and is used in the worker’s URL.</p></li><li><p><strong>Click “Save and Deploy”.</strong> Your worker is now deployed and live. You can test it directly in the Workers dashboard by requesting your worker’s URL.</p></li></ol><h3 id="setting-up-routes" tabindex="-1">Setting Up Routes <a class="header-anchor" href="#setting-up-routes" aria-label="Permalink to &quot;Setting Up Routes&quot;">​</a></h3><p>Once your worker is deployed, set up routes to ensure requests to the following endpoints are handled by the worker:</p><ul><li><p><code>/.well-known/matrix/client</code></p></li><li><p><code>/.well-known/matrix/server</code></p></li></ul><p>You can configure these routes in your Cloudflare dashboard under the <strong>Workers &gt; Routes</strong> section.</p><h3 id="categories" tabindex="-1">Categories <a class="header-anchor" href="#categories" aria-label="Permalink to &quot;Categories&quot;">​</a></h3><p>[Management]</p>`,16)])])}const m=a(t,[["render",o]]);export{h as __pageData,m as default};
